import {Explorer,DOCTORS,LANDMARKS} from './scene.js';
import {PhysicsPlayground} from './physics.js';
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const format=new Intl.NumberFormat('en-US'),decimal=new Intl.NumberFormat('en-US',{maximumFractionDigits:2});
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const SIZES={'4x6':{width:4,length:6},'5x7':{width:5,length:7},'6x8':{width:6,length:8}};
let explorer,playground,selected='kim',quantity=2000,displayCount=2000,size='5x7',displayLength=140,animation=null,raf=null;
const badge='<span class="verify-badge" aria-hidden="true">✓</span>';
function person(d){return `<span class="person-line">${d.name}<img class="flag" src="/assets/${d.country}.svg" alt="국적 ${d.countryName}"><button class="verify-trigger" aria-label="${d.name} 인증 정보 보기">${badge}</button></span>`;}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3000);}
function selectDoctor(id){selected=id;all('.doctor-card').forEach(card=>{const on=card.dataset.doctor===id;card.classList.toggle('selected',on);card.querySelector('.doctor-select').setAttribute('aria-pressed',String(on));});explorer?.focus(id);$('#all-view').classList.add('active');$('#my-tower').classList.remove('active');}
$('#doctor-list').innerHTML=DOCTORS.map(d=>`<div class="doctor-card ${d.id===selected?'selected':''}" data-doctor="${d.id}"><button class="doctor-select" aria-label="${d.name}의 ${format.format(d.length)}미터 탑 보기" aria-pressed="${d.id===selected}"></button><span class="avatar">${d.initials}</span><div class="doctor-details">${person(d)}<span class="person-value">${format.format(d.length)}<small>m</small></span><span class="person-hint">누적 사용 길이</span></div></div>`).join('');
all('.doctor-select').forEach(b=>b.addEventListener('click',()=>selectDoctor(b.closest('[data-doctor]').dataset.doctor)));
function attachBadges(){all('.verify-trigger:not([data-bound])').forEach(b=>{b.dataset.bound='true';b.setAttribute('aria-describedby','verification-popover');const pop=$('#verification-popover');const show=()=>{const rect=b.getBoundingClientRect();pop.style.left=`${Math.max(12,Math.min(rect.left-90,innerWidth-322))}px`;pop.style.top=`${Math.max(12,Math.min(rect.bottom+12,innerHeight-210))}px`;if(!pop.matches(':popover-open'))pop.showPopover();};b.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')show();});b.addEventListener('focus',show);b.addEventListener('click',e=>{e.stopPropagation();show();});b.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse'&&!b.matches(':focus-visible'))pop.hidePopover();});b.addEventListener('blur',()=>pop.hidePopover());});}
function renderRanking(){const filter=$('#country-filter').value,doctors=DOCTORS.filter(d=>filter==='all'||filter===d.country);$('#ranking-content').innerHTML=`<div class="ranking-table" role="table" aria-label="데모 전문의 누적 사용 길이 순위"><div class="ranking-header" role="row"><span role="columnheader">순위</span><span role="columnheader">전문의</span><span role="columnheader">누적 사용 길이</span><span role="columnheader">탐색</span></div>${doctors.map(d=>`<div class="ranking-row" role="row"><span role="cell" class="rank-number rank-${d.rank}">${String(d.rank).padStart(2,'0')}</span><div role="cell" class="ranking-person"><span class="avatar">${d.initials}</span>${person(d)}</div><span role="cell" class="ranking-value">${format.format(d.length)}<small>m</small></span><div role="cell" class="tower-cell"><button class="view-tower" data-view="${d.id}" aria-label="${d.name} 탑 보기">탑 보기 ↗</button></div></div>`).join('')}</div>`;all('[data-view]').forEach(b=>b.addEventListener('click',()=>{$('#explore').scrollIntoView({behavior:reduced?'instant':'smooth'});selectDoctor(b.dataset.view);}));attachBadges();}
$('#country-filter').addEventListener('change',renderRanking);renderRanking();
$('#play-content').innerHTML=`<div class="play-grid"><div class="play-visual"><div class="material-label"><b>THE SMALL PIECE</b><span>원본 사진 기반 3D</span></div><div id="play-canvas" class="play-canvas" role="group" aria-label="ADM 낙하 및 재질 체험"></div><div class="material-caption"><button id="inspect-material" aria-pressed="false">진피 자세히 보기 ↗</button><span>드래그하여 회전</span></div></div><div class="play-controls"><form id="quantity-form" novalidate><label class="control-title" for="quantity">몇 장을 이어 볼까요?<small>0–100,000장</small></label><div class="input-row"><div class="quantity-field"><input id="quantity" type="number" inputmode="numeric" min="0" max="100000" step="1" value="2000" aria-describedby="input-error"><span>장</span></div><button type="submit" class="primary-button">적용</button></div><p id="input-error" class="input-error" role="alert" hidden></p></form><div class="quick-buttons" aria-label="체험 수량 더하기">${[10,100,500,1000].map(n=>`<button data-add="${n}">+${format.format(n)}</button>`).join('')}</div><div class="reset-row"><button id="reset-count">↻ 처음부터 다시</button></div><div class="rule"></div><div class="control-title">진피 사이즈 <small>예시 규격 · cm</small></div><div class="size-options" role="group" aria-label="진피 사이즈">${Object.entries(SIZES).map(([key,s])=>`<button data-size="${key}" aria-pressed="${key===size}" class="${key===size?'active':''}">${s.width} × ${s.length}</button>`).join('')}</div><div class="metric-row"><div><div class="metric-value"><span id="count-value">2,000</span><small>장</small></div><p class="metric-label">체험 수량</p></div><div><div class="metric-value"><span id="length-value">140</span><small>m</small></div><p class="metric-label">긴 변으로 이은 길이</p></div></div><p class="formula" id="formula">2,000장 × 7 cm = 140 m</p><div class="simulation-status"><span class="progress-track"><i id="sim-progress"></i></span><span id="sim-status" role="status" aria-live="polite">수량을 더해 낙하를 시작하세요</span></div><button id="compare-sim" class="compare-sim">내 체험 탑을 랜드마크와 비교하기 ↗</button><p class="simulation-disclaimer">낙하는 대표 시트로 표현합니다. 체험 수량은 실제 기록과 별개이며, 규격과 두께 표현은 예시입니다.</p></div></div>`;
try{explorer=new Explorer($('#explorer-canvas'),id=>selectDoctor(id));}catch(error){console.error(error);$('#explorer-canvas').innerHTML='<div class="scene-error">3D 화면을 열 수 없습니다.<br>브라우저의 하드웨어 가속을 확인해 주세요.</div>';}
try{playground=new PhysicsPlayground($('#play-canvas'));}catch(error){console.error(error);$('#play-canvas').innerHTML='<div class="scene-error">3D 재질 체험을 불러오지 못했습니다.<br>수량과 길이 계산은 계속 사용할 수 있습니다.</div>';}
$('#play-canvas').addEventListener('physics-unavailable',()=>{$('#sim-status').textContent='물리 연출을 불러오지 못했습니다. 길이 계산은 가능합니다.';});
function error(message){$('#input-error').textContent=message;$('#input-error').hidden=false;$('#quantity').setAttribute('aria-invalid','true');}
function clearError(){$('#input-error').hidden=true;$('#quantity').removeAttribute('aria-invalid');}
function animateMetrics(duration=1800){animation={fromCount:displayCount,fromLength:displayLength,toCount:quantity,toLength:quantity*SIZES[size].length/100,start:performance.now(),duration:reduced?0:duration};$('#sim-status').textContent=duration>1000?'한 장씩, 길이가 쌓이는 중…':'새로운 길이에 맞추는 중…';if(!raf)raf=requestAnimationFrame(tick);}
function tick(now){raf=null;if(!animation)return;const t=animation.duration===0?1:Math.min(1,(now-animation.start)/animation.duration),ease=1-Math.pow(1-t,2);displayCount=Math.round(animation.fromCount+(animation.toCount-animation.fromCount)*ease);displayLength=animation.fromLength+(animation.toLength-animation.fromLength)*ease;$('#count-value').textContent=format.format(displayCount);$('#length-value').textContent=decimal.format(displayLength);$('#sim-progress').style.width=`${t*100}%`;explorer?.updateSimulation(displayLength);if(t<1)raf=requestAnimationFrame(tick);else{animation=null;$('#sim-status').textContent=`${format.format(quantity)}장, ${decimal.format(displayLength)}m가 되었습니다`;$('#formula').textContent=`${format.format(quantity)}장 × ${SIZES[size].length} cm = ${decimal.format(displayLength)} m`;if(explorer?.selected==='simulation')explorer.focus('simulation');}}
function setQuantity(next){if(!Number.isInteger(next)||next<0||next>100000){error('0부터 100,000까지의 정수로 입력해 주세요.');return false;}clearError();const delta=next-quantity;quantity=next;$('#quantity').value=String(next);if(delta>0){playground?.setInspect(false);$('#inspect-material').setAttribute('aria-pressed','false');playground?.burst(delta,next);}else if(delta<0)playground?.seed(next);animateMetrics(delta>0?2400:650);return true;}
function setSize(key){if(!SIZES[key])return false;size=key;all('[data-size]').forEach(b=>{const on=b.dataset.size===key;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});playground?.setSize(SIZES[key]);animateMetrics(750);return true;}
$('#quantity-form').addEventListener('submit',e=>{e.preventDefault();const raw=$('#quantity').value;if(raw.trim()==='')return error('체험할 장수를 입력해 주세요.');setQuantity(Number(raw));});all('[data-add]').forEach(b=>b.addEventListener('click',()=>setQuantity(quantity+Number(b.dataset.add))));all('[data-size]').forEach(b=>b.addEventListener('click',()=>setSize(b.dataset.size)));$('#reset-count').addEventListener('click',()=>{setQuantity(0);toast('체험 수량을 초기화했습니다.');});$('#inspect-material').addEventListener('click',e=>{const on=e.currentTarget.getAttribute('aria-pressed')!=='true';e.currentTarget.setAttribute('aria-pressed',String(on));playground?.setInspect(on);});
function showSimulation(){explorer?.showSimulation();$('#all-view').classList.remove('active');$('#my-tower').classList.add('active');}$('#compare-sim').addEventListener('click',()=>{$('#explore').scrollIntoView({behavior:reduced?'instant':'smooth'});showSimulation();});function overview(){explorer?.overview();$('#all-view').classList.add('active');$('#my-tower').classList.remove('active');}$('#all-view').addEventListener('click',overview);$('#reset-camera').addEventListener('click',overview);$('#my-tower').addEventListener('click',showSimulation);$('#auto-rotate').addEventListener('click',e=>{if(!explorer)return;explorer.auto=!explorer.auto;e.currentTarget.setAttribute('aria-pressed',String(explorer.auto));});
function toggleLandmark(id,on){const b=$(`[data-landmark="${id}"]`);if(!b)return;b.setAttribute('aria-pressed',String(on));b.classList.toggle('active',on);b.querySelector('.chip-check').textContent=on?'✓':'＋';explorer?.toggleLandmark(id,on);}all('[data-landmark]').forEach(b=>b.addEventListener('click',()=>toggleLandmark(b.dataset.landmark,b.getAttribute('aria-pressed')!=='true')));
const navObserver=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)all('.site-header nav a').forEach(a=>a.classList.toggle('nav-active',a.hash===`#${e.target.id}`));});},{rootMargin:'-10% 0px -60% 0px'});['explore','play','ranking'].forEach(id=>navObserver.observe($('#'+id)));
function state(){return {demo:true,quantity,size,unit:'cm',longEdgeMeters:quantity*SIZES[size].length/100,selectedTower:explorer?.selected??selected,landmarks:all('[data-landmark][aria-pressed="true"]').map(b=>b.dataset.landmark),ranking:DOCTORS.map(d=>({id:d.id,name:d.name,rank:d.rank,country:d.country,lengthMeters:d.length,verification:'demo'}))};}
const result=value=>({content:[{type:'text',text:JSON.stringify(value)}]});
if(document.modelContext?.registerTool){
 const register=tool=>{try{document.modelContext.registerTool(tool);}catch(error){console.warn('WebMCP registration:',error.message);}};
 register({name:'get_admerest_state',description:'Read demo quantity, size, visible landmarks and fictional professional ranking. No real patient records.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>result(state())});
 register({name:'set_adm_simulation',description:'Update this page’s local simulation. Does not modify professional records or ranking.',inputSchema:{type:'object',properties:{quantity:{type:'integer',minimum:0,maximum:100000},size:{type:'string',enum:Object.keys(SIZES)}},additionalProperties:false},execute:async input=>{if(input.quantity!==undefined&&(!Number.isInteger(input.quantity)||input.quantity<0||input.quantity>100000))throw new Error('Invalid quantity');if(input.size!==undefined&&!SIZES[input.size])throw new Error('Unknown size');if(input.quantity!==undefined)setQuantity(input.quantity);if(input.size!==undefined)setSize(input.size);return result(state());}});
 register({name:'focus_professional_tower',description:'Select a fictional professional and move the 3D camera to their tower.',inputSchema:{type:'object',properties:{id:{type:'string',enum:DOCTORS.map(d=>d.id)}},required:['id'],additionalProperties:false},execute:async({id})=>{if(!DOCTORS.some(d=>d.id===id))throw new Error('Unknown professional');selectDoctor(id);$('#explore').scrollIntoView({behavior:'instant'});return result(state());}});
 register({name:'set_comparison_landmarks',description:'Choose landmarks visible alongside the professional towers.',inputSchema:{type:'object',properties:{landmarks:{type:'array',items:{type:'string',enum:Object.keys(LANDMARKS)},uniqueItems:true}},required:['landmarks'],additionalProperties:false},execute:async({landmarks})=>{if(!Array.isArray(landmarks)||landmarks.some(id=>!LANDMARKS[id]))throw new Error('Unknown landmark');Object.keys(LANDMARKS).forEach(id=>toggleLandmark(id,landmarks.includes(id)));return result(state());}});
}
